# %% ../nbs/02_lazy_frame.ipynb 4
class LogicalPlan:
    """Base class for all logical plan nodes."""
    def signature(self) -> tuple:
        """Return a hashable structural signature for graph caching."""
        raise NotImplementedError(f"signature() not implemented for {type(self).__name__}")

@dataclass
class Scan(LogicalPlan):
    """Represents reading data from a source (e.g., a PyArrow Table)."""
    table: pa.Table
    def signature(self) -> tuple:
        return ("Scan", tuple(self.table.column_names))

@dataclass
class ParquetScan(LogicalPlan):
    """A Parquet file that has not been read yet (lazy source).

    Only the footer is read to build ``schema``.  At ``compute()`` time the
    source-resolution pass (``io_parquet.resolve_plan``) replaces it with a
    ``Scan`` holding just the columns the plan references, with simple
    comparisons that sit directly above it pushed into the reader.

    ``columns`` / ``filters`` are filled in by that pass (``None`` = not resolved).
    ``dictionary`` is ``"auto"`` (dictionary-encoded, low-cardinality strings),
    ``True`` (every string column), ``False`` (none) or a list of column names.
    """
    path: str
    schema: pa.Schema
    dictionary: Any = "auto"
    max_dictionary_bytes: int = 64 * 1024
    columns: Optional[tuple] = None
    filters: Optional[tuple] = None
    def signature(self) -> tuple:
        return ("ParquetScan", self.path, tuple(self.schema.names),
                self.columns, self.filters)

@dataclass
class Filter(LogicalPlan):
    """Represents filtering rows based on a predicate."""
    input: LogicalPlan
    predicate: Expr
    def signature(self) -> tuple:
        return ("Filter", self.input.signature(), self.predicate.signature())

@dataclass
class Project(LogicalPlan):
    """Represents selecting or computing columns."""
    input: LogicalPlan
    exprs: List[Expr]
    def signature(self) -> tuple:
        return ("Project", self.input.signature(), tuple(e.signature(True) for e in self.exprs))

@dataclass
class Aggregate(LogicalPlan):
    """Represents grouping and aggregating data."""
    input: LogicalPlan
    group_by: List[Expr]
    aggs: List[Expr]
    def signature(self) -> tuple:
        return ("Aggregate", self.input.signature(),
                tuple(e.signature(True) for e in self.group_by),
                tuple(e.signature(True) for e in self.aggs))

@dataclass
class Sort(LogicalPlan):
    """Represents sorting rows by one or more keys."""
    input: LogicalPlan
    by: List[Expr]
    descending: List[bool]
    def signature(self) -> tuple:
        return ("Sort", self.input.signature(),
                tuple(e.signature() for e in self.by),
                tuple(self.descending))

@dataclass
class Limit(LogicalPlan):
    """Represents taking N rows after skipping the first ``offset`` (OFFSET m LIMIT n). ``n`` is None for
    "no limit" (SQL OFFSET without LIMIT): every row after the skipped ones."""
    input: LogicalPlan
    n: Optional[int]
    offset: int = 0
    def signature(self) -> tuple:
        return ("Limit", self.input.signature(), self.n, self.offset)

@dataclass
class Distinct(LogicalPlan):
    """Represents removing duplicate rows (optionally on a subset of columns)."""
    input: LogicalPlan
    subset: Optional[List[str]] = None
    def signature(self) -> tuple:
        return ("Distinct", self.input.signature(),
                tuple(self.subset) if self.subset else ())


@dataclass
class Tail(LogicalPlan):
    """Represents taking the last N rows."""
    input: LogicalPlan
    n: int
    def signature(self) -> tuple:
        return ("Tail", self.input.signature(), self.n)


JOIN_TYPES = ("inner", "left", "semi", "anti")
FILTERING_JOINS = ("semi", "anti")      # keep or drop left rows; no right column in the output


def join_output_names(left_names, right_names, right_on):
    """``[(right column, output name), ...]`` for the right side's non-key columns of a join.

    A right column whose name is already taken (by the left side or an earlier right column)
    is renamed with a ``_right`` suffix (``_right2``, ... when that is taken too), like Polars,
    so a join result never holds two columns of one name."""
    left = set(left_names)
    right = [c for c in right_names if c not in right_on]
    taken = left | {c for c in right if c not in left}          # names that are kept as they are
    out = []
    for c in right:
        name, i = c, 1
        if c in left:
            while True:
                name = f"{c}_right" if i == 1 else f"{c}_right{i}"
                i += 1
                if name not in taken and name not in right:
                    break
            taken.add(name)
        out.append((c, name))
    return out


def column_types(plan) -> dict:
    """{column name: Arrow type} for the columns of *plan* that are plain columns of a table, carried
    through filters, sorts, joins and renaming selects; computed columns are absent."""
    if isinstance(plan, Scan):
        return {f.name: f.type for f in plan.table.schema}
    if isinstance(plan, ParquetScan):
        return {f.name: f.type for f in plan.schema}
    if isinstance(plan, (Filter, Sort, Limit, Distinct, Tail)):
        return column_types(plan.input)
    if isinstance(plan, Join):
        left, right = column_types(plan.left), column_types(plan.right)
        return {n: t for n, t in {**right, **left}.items()
                if n not in left or n not in right or left[n] == right[n]}
    if isinstance(plan, Project):
        inner = column_types(plan.input)
        return {(e._alias or e.args[0]): inner[e.args[0]]
                for e in plan.exprs if e.op == "col" and e.args[0] in inner}
    return {}


@dataclass
class Join(LogicalPlan):
    """Represents an inner join between two plan trees (first two-child node)."""
    left: LogicalPlan
    right: LogicalPlan
    left_on: List[str]
    right_on: List[str]
    how: str = "inner"
    def signature(self) -> tuple:
        return ("Join", self.left.signature(), self.right.signature(),
                tuple(self.left_on), tuple(self.right_on), self.how)


