DeviceType = Literal["cpu", "gpu", "auto"]


class LazyFrame:
    """A lazy DataFrame that builds a logical plan."""
    def __init__(self, plan):
        if isinstance(plan, pa.Table):
            plan = Scan(plan)
        self.plan = plan
        self._last_compile_provenance = None
        self._last_optimizer_trace = []
        self.last_auto_decision = None

    def select(self, *exprs):
        """Select columns or compute new ones."""
        parsed_exprs = [col(e) if isinstance(e, str) else e for e in exprs]
        return LazyFrame(Project(self.plan, parsed_exprs))

    def with_columns(self, *exprs):
        """Add or replace columns preserving all existing ones.

        Numeric arithmetic is compiled to MAX Graph ops (Mojo); case_when/isin/
        string ops fall through to the engine thin PyArrow pre-compute layer.
        """
        new_aliases = {e._alias for e in exprs if e._alias}
        def _scan_cols(p):
            if isinstance(p, Scan):
                return list(p.table.column_names)
            if isinstance(p, ParquetScan):
                return list(p.schema.names)
            if hasattr(p, "input"):
                return _scan_cols(p.input)
            return []
        from .optimizer import _output_columns
        existing = _output_columns(self.plan)          # what the plan produces (an aggregate's keys and aggs, not the scan's)
        if existing is None:
            existing = _scan_cols(self.plan)
        passthrough = [col(c) for c in existing if c not in new_aliases]
        return LazyFrame(Project(self.plan, passthrough + list(exprs)))

    def filter(self, predicate):
        """Filter rows based on a condition."""
        return LazyFrame(Filter(self.plan, predicate))

    def scalar(self, agg) -> Expr:
        """A one-value subquery: SQL's ``(SELECT <agg> FROM this)``, for use inside an expression of another
        plan (a ``filter``, a ``with_columns``, a HAVING)::

            total = sales.scalar(col("value").sum())
            sales.groupby("k").agg(col("value").sum().alias("v")).filter(col("v") > total * lit(0.0001))

        ``agg`` is one aggregate (sum, min, max, mean or count). ``compute()`` runs each subquery first, as its
        own native plan, and puts the value in the expression as a literal (the same literal a hand-written
        ``lit(value)`` would be, so comparisons against float32 columns behave as before); the main plan then
        needs no Python round trip over rows. A subquery over no rows is NULL (a comparison with it keeps no
        rows, as in SQL)."""
        if not (isinstance(agg, Expr) and agg.op in ("sum", "min", "max", "mean", "count")):
            raise ValueError("scalar() takes one aggregate expression: sum, min, max, mean or count")
        return Expr("scalar", Aggregate(self.plan, [], [Expr(agg.op, *agg.args).alias("__scalar")]))

    def groupby(self, *by):
        """Group data by one or more columns."""
        parsed_by = [col(b) if isinstance(b, str) else b for b in by]
        return LazyGroupBy(self, parsed_by)

    def sink_parquet(self, path, device: str = "cpu", *, compression: str = "zstd", **kwargs) -> int:
        """Run the query and write the result to the Parquet file ``path``; returns the rows written (F-113).

        Takes the arguments of ``compute``. A result bigger than the host memory budget (``compute()`` raises a
        ``MemoryError`` for it) is streamed into the file piece by piece with bounded memory: the batches of a
        filter, spilled groups, join pairs, sorted ranges. The file appears only when the query has finished."""
        from . import streamed as _streamed
        return _streamed.sink_parquet(self, path, device, compression=compression, **kwargs)

    def compute(
        self,
        device: DeviceType = "auto",
        verbose: bool = False,
        optimize: bool = True,
        validate: bool = True,
        *,
        prefer: Optional[str] = None,
        placement: Optional[Dict[str, str]] = None,
        gpu_fraction: Optional[float] = None,
        strict: bool = False,
        profile: bool = False,
        reproducible: Optional[bool] = None,
    ) -> pa.Table:
        """Execute the logical plan and return the result.

        Args:
            device: "auto" (default), "cpu", or "gpu".
                "auto" — estimate the query on each device from this machine's
                         calibration (`mx.calibrate()`), including copies over the
                         CPU↔GPU link and GPU start-up, and run it on the cheaper one.
                         A GPU error reruns the query on CPU (warning once per query shape).
                "cpu"  — always run on CPU.
                "gpu"  — run on GPU; raises RuntimeError if no GPU is available. A piece (aggregate,
                         join, sort) that does not fit the GPU's free memory, or runs out of it, is
                         rerun on the CPU with a warning (`explain(include_runtime=True)` says why).
            verbose: if True, print compile/execute timing and cache status.
            optimize: if True (default), run logical plan optimization passes first.
            validate: if True (default), validate logical plan invariants before execution.
            prefer: auto only; "gpu" or "cpu" biases the choice without forcing it.
            placement: auto only; e.g. {"join": "gpu"}. Phase 1 places the whole
                query: any "gpu" value runs the query on GPU, all "cpu" on CPU.
            gpu_fraction: auto only; fixed GPU share of rows when a fused aggregate
                co-processes on CPU and GPU (default: balanced from calibration).
            strict: raise GPU errors, including a piece that does not fit the GPU's memory or runs
                out of it (a `MemoryError` with the estimate), instead of falling back to CPU.
            profile: auto only; record the actual query time next to the estimate
                (see `last_auto_decision`). Per-operator timings that refine the
                calibration arrive with per-operator placement.
            reproducible: ``True`` makes every native CPU float SUM / MEAN bit-identical from run to run
                whatever the number of groups (default: ``MXFRAME_REPRODUCIBLE=1`` or off). By default the
                defined order of additions runs only where it is as fast as before: global aggregates and
                fused joins with 16,384 or more groups; every other group-by keeps the previous fastest
                code, whose sums can differ in the last bits between runs. Costs 0-20% on keyed group-bys.
                ``False`` overrides the environment variable. On ``device="gpu"`` and in a CPU+GPU split the GPU adds without atomics (an ordered
                table per block, blocks merged in block order) while (slots + 1) x groups <= 4,096 and the
                table fits shared memory; with more groups the GPU declines and the CPU's defined order runs
                (provenance path ``fused_pipeline_cpu``). ``device="auto"`` with this flag runs the CPU defined order (no GPU,
                no split). Default mode keeps the faster atomics (F-067).
        """
        if reproducible is not None:
            # carried to the native call as a plan flag by a per-thread context variable (no process-wide
            # state: concurrent computes in other threads keep their own mode)
            from . import native_exec as _nx
            tok = _nx._reproducible.set(bool(reproducible))
            try:
                return self.compute(device, verbose, optimize, validate, prefer=prefer, placement=placement,
                                    gpu_fraction=gpu_fraction, strict=strict, profile=profile)
            finally:
                _nx._reproducible.reset(tok)
        from .io_parquet import resolve_plan
        plan = _resolve_scalars(self.plan, device, strict)
        optimizer_trace = None

        if validate:
            from .plan_validation import validate_plan_or_raise
            validate_plan_or_raise(plan)

        if optimize:
            # Optimize before the Parquet sources are read: filters the optimizer moves below a join land
            # directly above their ParquetScan, where the reader applies them while decoding (F-017).
            from .optimizer import optimize_plan
            opt = optimize_plan(plan)
            plan = opt.plan
            optimizer_trace = opt.trace
            if verbose and opt.trace:
                print("[mxframe] optimizer passes:")
                for line in opt.trace:
                    print(f"  - {line}")

        from . import streamed as _streamed
        got = _streamed.try_stream(self, plan, device, strict=strict, prefer=prefer, placement=placement,
                                   gpu_fraction=gpu_fraction, verbose=verbose)
        if got is not None:                 # the sources are bigger than memory: ran in batches of row groups (F-056)
            self._last_optimizer_trace = list(optimizer_trace or [])
            self._last_compile_provenance = got[1]
            return got[0]

        # COUNT(DISTINCT b) per a counts dictionary codes on the native CPU path (F-046h); auto runs that shape
        # there too (F-058), unless the caller steers it to the GPU, which needs the columns decoded
        cd_codes = device == "cpu" or (device == "auto" and _auto_may_count_codes(plan, prefer, placement))
        plan = resolve_plan(plan, count_distinct_codes=cd_codes)
        if validate:
            from .plan_validation import validate_plan_or_raise
            validate_plan_or_raise(plan)

        self._last_optimizer_trace = list(optimizer_trace or [])
        if device != "auto":
            result, prov = _run_on_device(plan, device, verbose=verbose, optimizer_trace=optimizer_trace,
                                          strict=strict)
            self._last_compile_provenance = prov
            return result

        from . import auto_mode as _am
        import time as _t
        decision = (_auto_codes_decision(plan) if cd_codes else None) \
            or _am.choose_device(plan, prefer=prefer, placement=placement)
        self.last_auto_decision = decision
        if verbose:
            print(decision.explain())
        t0 = _t.perf_counter()
        if decision.device == "gpu":
            try:
                result, prov = _run_on_device(plan, "gpu", verbose=verbose, optimizer_trace=optimizer_trace,
                                              strict=strict, auto=True)
                if prov.get("gpu_pieces_oom") is not None:      # a piece ran out of GPU memory and went to the CPU (F-056)
                    _am.remember_gpu_failure(plan, prov["gpu_pieces_oom"])
                decision.pieces = prov.get("gpu_pieces", "")
            except Exception as err:
                if strict:
                    raise
                _am.remember_gpu_failure(plan, _oom_free(err))
                if _am.is_sticky_gpu_error(err):
                    _am.disable_gpu(f"{type(err).__name__}: {err}")
                _am.warn_fallback_once(plan, err)
                decision.device, decision.fallback = "cpu", True
                result, prov = _run_on_device(plan, "cpu", verbose=verbose, optimizer_trace=optimizer_trace)
        else:
            # CPU plan: fused aggregates may still co-process with the GPU once their
            # columns are resident there (see coproc_fused), and start that upload otherwise.
            import contextlib as _contextlib
            from . import coproc_fused as _cf
            with _cf.deferred_background() as _bg:
                if decision.estimate is not None and decision.gpu_available and not _am.gpu_warmup_started():
                    # GPU start-up for later queries waits until this CPU query has returned.
                    _bg.later(lambda: _am.get_gpu_warmup().start())
                if decision.upload and not _streamed.active():     # a streamed batch is never seen again
                    # A split would win once the columns are on the GPU (F-057): this query runs native, and the
                    # upload (group ids, then the columns) starts when it has returned.
                    from . import pipeline_exec as _pe
                    _bg.later(lambda: _pe.queue_resident_upload(plan))
                # The policy makes the native executor decline, so it is set only for a predicted
                # CPU+GPU split (or one the caller forces with gpu_fraction); every other CPU
                # decision runs exactly as device="cpu" (F-053).
                forced = gpu_fraction is not None
                pol = _cf.policy(gpu_fraction=gpu_fraction) if decision.split or forced else _contextlib.nullcontext()
                with pol, _cf.query_running():
                    result, prov = _run_on_device(plan, "cpu", verbose=verbose, optimizer_trace=optimizer_trace)
        if profile:
            decision.actual_ms = (_t.perf_counter() - t0) * 1e3
        prov = dict(prov)
        if prov.get("coproc"):
            decision.coproc = prov["coproc"]
        prov["auto_device"] = decision.device
        prov["auto_reason"] = decision.reason
        self._last_compile_provenance = prov
        return result

    def explain(
        self,
        optimized: bool = True,
        validate: bool = False,
        include_runtime: bool = False,
        device: Optional[str] = None,
        costs: bool = False,
    ) -> str:
        """Return a readable plan explanation.

        Args:
            optimized: if True (default), include optimizer pass trace and optimized plan.
            validate: if True, include validation summaries for shown plans.
            include_runtime: if True, include last compile provenance from compute().
            device: "auto" adds the device decision (with `costs=True`, the
                per-operator estimates on each device) without running the query.
        """
        from .io_parquet import resolve_plan
        trace = []
        # Show what would be read (columns, pushed filters) without reading data.
        original_plan = resolve_plan(self.plan, read=False)
        plan = original_plan
        title = "LogicalPlan"
        if optimized:
            from .optimizer import optimize_plan
            opt = optimize_plan(self.plan)
            plan = opt.plan
            trace = opt.trace
            title = "OptimizedPlan"

        lines = [title, _format_plan(plan)]
        if validate:
            from .plan_validation import validate_plan
            shown_errors = validate_plan(plan)
            lines.append("Validation")
            lines.append("ok" if not shown_errors else f"errors={len(shown_errors)}")
            if optimized:
                orig_errors = validate_plan(original_plan)
                lines.append("OriginalValidation")
                lines.append("ok" if not orig_errors else f"errors={len(orig_errors)}")
        if optimized:
            lines.append("PassTrace")
            lines.extend(trace if trace else ["no-op"])
        from . import streamed as _streamed
        stream = _streamed.describe(plan, device if device in ("cpu", "gpu") else "cpu")
        if stream is not None:                         # a lazy Parquet source: will it stream (F-056 step 2)?
            lines.extend(["Streaming", stream])
        if include_runtime:
            lines.append("LastCompileProvenance")
            if self._last_compile_provenance:
                for k, v in self._last_compile_provenance.items():
                    lines.append(f"{k}={v}")
            else:
                lines.append("none (run compute() first)")
        if device == "auto":
            from . import auto_mode as _am
            decision = (_auto_codes_decision(plan) if _auto_may_count_codes(plan, None, None) else None) \
                or _am.choose_device(plan, quick=not costs)
            text = decision.explain()
            lines.append("AutoDecision")
            shown = text.splitlines()
            if not costs:
                shown = shown[:2] if decision.cpu_path and decision.device == "cpu" else shown[:1]
            lines.extend(shown)
        return "\n".join(lines)

    @property
    def last_compile_provenance(self) -> dict:
        """Return last compile/execute provenance captured during compute()."""
        return dict(self._last_compile_provenance or {})


    def sort(self, *by, descending=False):
        """Sort rows by one or more columns.

        Args:
            *by: Column names (str) or Expr objects to sort by.
            descending: bool or list of bool. If a single bool, applied to all keys.
        """
        parsed_by = [col(b) if isinstance(b, str) else b for b in by]
        if isinstance(self.plan, Project):             # select() dropped the columns it does not list
            have = [e._alias or (e.args[0] if e.op == "col" else None) for e in self.plan.exprs]
            if None not in have:
                for b in parsed_by:
                    if b.op == "col" and b.args[0] not in have:
                        raise ValueError(f"cannot sort by column {b.args[0]!r}: select() did not keep it "
                                         f"(columns here: {have}); sort before select")
        if isinstance(descending, bool):
            desc_list = [descending] * len(parsed_by)
        else:
            desc_list = list(descending)
        return LazyFrame(Sort(self.plan, parsed_by, desc_list))

    def limit(self, n: Optional[int], offset: int = 0):
        """Take N rows, after skipping the first ``offset`` (SQL ``LIMIT n OFFSET offset``); ``n=None``: all the rest."""
        return LazyFrame(Limit(self.plan, n, offset))

    def distinct(self, *subset):
        """Remove duplicate rows, optionally considering only a subset of columns.

        Args:
            *subset: Column names to consider for uniqueness.
                     If empty, all columns are used.
        """
        sub = list(subset) if subset else None
        return LazyFrame(Distinct(self.plan, sub))

    def head(self, n: int = 5):
        return self.limit(n)

    def tail(self, n: int = 5):
        """Return the last N rows (lazy)."""
        return LazyFrame(Tail(self.plan, n))

    def to_pandas(self):
        return self.compute().to_pandas()

    def to_polars(self):
        import polars as pl
        return pl.from_arrow(self.compute())

    def to_arrow(self):
        return self.compute()

    @property
    def schema(self) -> 'pa.Schema':
        """Return the output schema without computing the full result.

        For plain Scan plans, returns the schema directly.
        For all other plans, runs a zero-row dry-run to infer output columns and types.
        """
        if isinstance(self.plan, Scan):
            return self.plan.table.schema
        if isinstance(self.plan, ParquetScan):
            return self.plan.schema
        def _zero(p):
            if isinstance(p, Scan):      return Scan(p.table.slice(0, 0))
            if isinstance(p, ParquetScan): return Scan(_empty(p.schema))
            if isinstance(p, Join):      return Join(_zero(p.left), _zero(p.right), p.left_on, p.right_on, p.how)
            if isinstance(p, Filter):    return Filter(_zero(p.input), p.predicate)
            if isinstance(p, Project):   return Project(_zero(p.input), p.exprs)
            if isinstance(p, Aggregate): return Aggregate(_zero(p.input), p.group_by, p.aggs)
            if isinstance(p, Sort):      return Sort(_zero(p.input), p.by, p.descending)
            if isinstance(p, Limit):     return Limit(_zero(p.input), p.n, p.offset)
            if isinstance(p, Tail):      return Tail(_zero(p.input), p.n)
            if isinstance(p, Distinct):  return Distinct(_zero(p.input), p.subset)
            return p
        try:
            result = LazyFrame(_zero(self.plan)).compute(validate=False, optimize=False)
            return result.schema
        except Exception:
            return None

    def describe(self, device: DeviceType = "auto") -> 'pa.Table':
        """Compute summary statistics for all numeric columns.

        Returns a pa.Table with rows: count, mean, std, min, 25%, 50%, 75%, max.
        Non-numeric columns are silently skipped.
        """
        import numpy as _np
        result = self.compute(device=device)
        numeric_cols: dict = {}
        for name in result.column_names:
            arr = result.column(name)
            if isinstance(arr, pa.ChunkedArray):
                arr = _combine(arr)
            if pa.types.is_integer(arr.type) or pa.types.is_floating(arr.type):
                np_arr = _np_of(arr, zero_copy_only=False).astype(_np.float64)
                numeric_cols[name] = np_arr[~_np.isnan(np_arr)]
        stat_names = ["count", "mean", "std", "min", "25%", "50%", "75%", "max"]
        stats: dict = {"statistic": _npa(stat_names)}
        for name, vals in numeric_cols.items():
            n = len(vals)
            stats[name] = _npa([
                float(n),
                float(_np.mean(vals))              if n > 0 else float("nan"),
                float(_np.std(vals, ddof=1))       if n > 1 else 0.0,
                float(_np.min(vals))               if n > 0 else float("nan"),
                float(_np.percentile(vals, 25))    if n > 0 else float("nan"),
                float(_np.median(vals))            if n > 0 else float("nan"),
                float(_np.percentile(vals, 75))    if n > 0 else float("nan"),
                float(_np.max(vals))               if n > 0 else float("nan"),
            ])
        return pa.table(stats)


    def to_gpu(self) -> 'GPUFrame':
        """Upload all numeric columns to GPU once and return a GPUFrame.

        The GPUFrame holds the device buffers in the module-level
        ``_GPU_BUFFER_CACHE`` so that every subsequent ``.compute()`` call
        on the same underlying data skips the PCIe transfer entirely.

        Raises ``RuntimeError`` if no GPU is available.
        """
        from .custom_ops import CustomOpsCompiler, _GPU_BUFFER_CACHE
        from max import driver
        import pyarrow as pa
        import numpy as np
        from pathlib import Path

        compiler_inst = CustomOpsCompiler(device="gpu")

        # Warm the GPU buffer cache by converting and uploading all numeric columns.
        table = self.plan.table if hasattr(self.plan, 'table') else None
        if table is None:
            raise ValueError("to_gpu() requires a LazyFrame built directly from a pa.Table (no prior transforms).")

        col_names = []
        gpu_bufs: Dict[str, Any] = {}
        for name in table.column_names:
            col = table.column(name)
            if isinstance(col, pa.ChunkedArray):
                col = _combine(col)
            np_arr, _, _ = compiler_inst._column_to_numpy_cached(col)
            if np_arr is None:
                continue
            np_arr = compiler_inst._normalize_numeric_dtype(np_arr)
            if np_arr is None:
                continue
            col_names.append(name)
            gpu_buf, _ = compiler_inst._to_gpu_input(np_arr)
            gpu_bufs[name] = gpu_buf

        # Store under a stable key (no filter, no plan-specific signature)
        # so filter variations all reuse these buffers.
        stable_key = (id(table), table.num_rows, tuple(col_names), "gpu")
        from .custom_ops import _watch_table
        _watch_table(table)
        _GPU_BUFFER_CACHE[stable_key] = gpu_bufs

        return GPUFrame(table, _compiler=compiler_inst)


    def join(self, other, *, on=None, left_on=None, right_on=None, how="inner"):
        """Join with another LazyFrame.

        Args:
            other: LazyFrame to join with.
            on: Column name(s) present in both frames (shorthand for left_on=right_on).
            left_on: Column name(s) in the left frame.
            right_on: Column name(s) in the right frame.
            how: "inner", "left" (every left row; right columns null without a partner), "semi" (the
                left rows that have a partner, each once) or "anti" (the left rows that have none).
                Semi and anti joins return the left columns only, in the left table's row order;
                null keys never match (SQL EXISTS / NOT EXISTS).
        """
        if how not in JOIN_TYPES:
            raise ValueError(f"Unsupported join type {how!r}; use one of {', '.join(JOIN_TYPES)}")
        if on is not None:
            if left_on is not None or right_on is not None:
                raise ValueError("Cannot specify both 'on' and 'left_on'/'right_on'")
            left_on = [on] if isinstance(on, str) else list(on)
            right_on = list(left_on)
        else:
            if left_on is None or right_on is None:
                raise ValueError("Must specify either 'on' or both 'left_on' and 'right_on'")
            left_on = [left_on] if isinstance(left_on, str) else list(left_on)
            right_on = [right_on] if isinstance(right_on, str) else list(right_on)
        return LazyFrame(Join(self.plan, other.plan, left_on, right_on, how))


class LazyGroupBy:
    """Intermediate object for grouping operations."""
    def __init__(self, df, by):
        self.df = df
        self.by = by

    def agg(self, *aggs) -> LazyFrame:
        """Compute aggregations for each group."""
        return LazyFrame(Aggregate(self.df.plan, self.by, list(aggs)))


def _format_plan(plan: LogicalPlan, indent: int = 0) -> str:
    """Pretty-print a logical plan tree."""
    pad = "  " * indent
    if isinstance(plan, Scan):
        return f"{pad}Scan(columns={list(plan.table.column_names)})"
    if isinstance(plan, ParquetScan):
        cols = list(plan.columns) if plan.columns is not None else list(plan.schema.names)
        extra = f", filters={list(plan.filters)}" if plan.filters else ""
        return f"{pad}ParquetScan(path={plan.path!r}, columns={cols}{extra})"
    if isinstance(plan, Filter):
        head = f"{pad}Filter(predicate={plan.predicate.signature()})"
        return "\n".join([head, _format_plan(plan.input, indent + 1)])
    if isinstance(plan, Project):
        exprs = [e.signature() for e in plan.exprs]
        head = f"{pad}Project(exprs={exprs})"
        return "\n".join([head, _format_plan(plan.input, indent + 1)])
    if isinstance(plan, Aggregate):
        group_by = [e.signature() for e in plan.group_by]
        aggs = [e.signature() for e in plan.aggs]
        head = f"{pad}Aggregate(group_by={group_by}, aggs={aggs})"
        return "\n".join([head, _format_plan(plan.input, indent + 1)])
    if isinstance(plan, Sort):
        by = [e.signature() for e in plan.by]
        head = f"{pad}Sort(by={by}, descending={plan.descending})"
        return "\n".join([head, _format_plan(plan.input, indent + 1)])
    if isinstance(plan, Limit):
        args = ([] if plan.n is None else [f"n={plan.n}"]) + ([f"offset={plan.offset}"] if plan.offset else [])
        head = f"{pad}Limit({', '.join(args)})"
        return "\n".join([head, _format_plan(plan.input, indent + 1)])
    if isinstance(plan, Distinct):
        head = f"{pad}Distinct(subset={plan.subset})"
        return "\n".join([head, _format_plan(plan.input, indent + 1)])
    if isinstance(plan, Tail):
        head = f"{pad}Tail(n={plan.n})"
        return "\n".join([head, _format_plan(plan.input, indent + 1)])
    if isinstance(plan, Join):
        head = f"{pad}Join(how={plan.how}, left_on={plan.left_on}, right_on={plan.right_on})"
        left = _format_plan(plan.left, indent + 1)
        right = _format_plan(plan.right, indent + 1)
        return "\n".join([head, left, right])
    return f"{pad}{type(plan).__name__}"


class GPUFrame:
    """A GPU-resident DataFrame that holds column buffers on the device.

    Created via ``LazyFrame.to_gpu()`` — uploads all numeric columns once and
    keeps the device buffers alive across multiple ``.compute()`` calls.
    Subsequent queries on the same data skip the PCIe upload entirely because
    the ``_GPU_BUFFER_CACHE`` already contains the buffers.

    Usage::

        gdf = df.to_gpu()                          # upload once
        result1 = gdf.filter(col('a') > 5)\\
                      .groupby('dept').agg(col('salary').sum())\\
                      .compute()                   # no upload
        result2 = gdf.filter(col('a') > 10)\\
                      .groupby('dept').agg(col('salary').mean())\\
                      .compute()                   # still no upload

    The wrapped ``LazyFrame`` API (``filter``, ``select``, ``groupby``,
    ``sort``, ``limit``, ``distinct``, ``join``) is fully supported.
    Call ``.to_arrow()`` on any result to get a ``pa.Table``.
    """

    def __init__(self, table: pa.Table, _compiler=None):
        """Do not call directly — use ``LazyFrame.to_gpu()``."""
        self._table = table
        self._lf = LazyFrame(table)
        self._compiler = _compiler  # CustomOpsCompiler with warm session + pre-cached buffers

    # ── Lazy plan builders (delegate to wrapped LazyFrame) ──────────

    def filter(self, predicate) -> 'GPUFrame':
        return GPUFrame(self._table, self._compiler).__with_lf(self._lf.filter(predicate))

    def select(self, *exprs) -> 'GPUFrame':
        return GPUFrame(self._table, self._compiler).__with_lf(self._lf.select(*exprs))

    def sort(self, *by, descending=False) -> 'GPUFrame':
        return GPUFrame(self._table, self._compiler).__with_lf(self._lf.sort(*by, descending=descending))

    def limit(self, n: int, offset: int = 0) -> 'GPUFrame':
        return GPUFrame(self._table, self._compiler).__with_lf(self._lf.limit(n, offset))

    def tail(self, n: int = 5) -> 'GPUFrame':
        return GPUFrame(self._table, self._compiler).__with_lf(self._lf.tail(n))

    def distinct(self, subset=None) -> 'GPUFrame':
        return GPUFrame(self._table, self._compiler).__with_lf(self._lf.distinct(subset))

    def groupby(self, *by) -> 'LazyGroupBy':
        return _GPUGroupBy(self, [col(b) if isinstance(b, str) else b for b in by])

    def __with_lf(self, lf: 'LazyFrame') -> 'GPUFrame':
        gf = GPUFrame(self._table, self._compiler)
        gf._lf = lf
        return gf

    # ── Execution ────────────────────────────────────────────────────

    def compute(self, verbose: bool = False, optimize: bool = True,
                validate: bool = True) -> pa.Table:
        """Execute the plan on GPU, reusing cached device buffers.

        Always runs on ``device='gpu'``; raises ``RuntimeError`` if no GPU
        is available.
        """
        return self._lf.compute(
            device="gpu",
            verbose=verbose,
            optimize=optimize,
            validate=validate,
        )

    def to_arrow(self) -> pa.Table:
        """Alias for ``compute()`` — explicit pull of result to CPU."""
        return self.compute()

    def head(self, n: int = 5):
        return self.limit(n)

    def to_pandas(self):
        return self.compute().to_pandas()

    def to_polars(self):
        import polars as pl
        return pl.from_arrow(self.compute())


    def __repr__(self) -> str:
        return (f"GPUFrame(rows={self._table.num_rows}, "
                f"cols={self._table.column_names})")


class _GPUGroupBy:
    """Intermediate groupby object for GPUFrame."""

    def __init__(self, gf: GPUFrame, by):
        self._gf = gf
        self._by = by

    def agg(self, *aggs) -> GPUFrame:
        lf_agg = LazyFrame(Aggregate(self._gf._lf.plan, self._by, list(aggs)))
        gf = GPUFrame(self._gf._table, self._gf._compiler)
        gf._lf = lf_agg
        return gf






def _is_null(e) -> bool:
    return isinstance(e, Expr) and e.op == "lit" and len(e.args) == 1 and e.args[0] is None


def _bool_of(e):
    """True / False for a boolean literal, else None."""
    if isinstance(e, Expr) and e.op == "lit" and len(e.args) == 1 and isinstance(e.args[0], bool):
        return e.args[0]
    return None


def _num_of(e):
    if isinstance(e, Expr) and e.op == "lit" and len(e.args) == 1 and not isinstance(e.args[0], bool) \
            and isinstance(e.args[0], (int, float)):
        return e.args[0]
    return None


def _fold_subquery_value(op: str, args) -> Optional[Expr]:
    """One node of an expression whose operands include a subquery's value, simplified when its operands are
    constants: ``lit(a) <op> lit(b)`` as one literal (a HAVING compares an aggregate with a number only), NULL
    through arithmetic, comparisons and NOT, boolean literals through AND / OR. None: nothing to simplify (an
    integer division, a division by zero, integers past 2^53 are left to the engine)."""
    from .lazy_expr import lit
    if op in ("add", "sub", "mul", "div", "lt", "le", "gt", "ge", "eq", "ne"):
        if any(_is_null(a) for a in args):
            return lit(None)                       # NULL <op> x is NULL
        if op in ("add", "sub", "mul", "div"):
            a, b = (_num_of(x) for x in args)
            if a is None or b is None:
                return None
            if op == "div":
                if b == 0 or (isinstance(a, int) and isinstance(b, int)):
                    return None
                r = a / b
            else:
                r = a + b if op == "add" else a - b if op == "sub" else a * b
            return None if isinstance(r, int) and abs(r) > 2 ** 53 else lit(r)
        a, b = (_num_of(x) for x in args)          # two constants compared (NOT IN's emptiness / NULL test)
        if a is None or b is None or abs(a) > 2 ** 53 or abs(b) > 2 ** 53 or a != a or b != b:
            return None                            # (a NaN orders above every number: the engine's compares know that)
        return lit({"lt": a < b, "le": a <= b, "gt": a > b, "ge": a >= b, "eq": a == b, "ne": a != b}[op])
    if op == "not":
        if _is_null(args[0]):
            return lit(None)
        b = _bool_of(args[0])
        return None if b is None else lit(not b)
    if op in ("and", "or"):
        absorbing, identity = (False, True) if op == "and" else (True, False)
        if any(_bool_of(a) is absorbing for a in args):
            return lit(absorbing)
        rest = [a for a in args if _bool_of(a) is not identity]
        if not rest:
            return lit(identity)
        if all(_is_null(a) for a in rest):
            return lit(None)
        return rest[0] if len(rest) == 1 else Expr(op, *rest)
    return None


def _top_truth(p: Expr) -> Expr:
    """A filter keeps a row only when its predicate is TRUE, so a NULL there (a comparison with an empty
    subquery) is false, also inside AND / OR chains: ``a AND NULL`` is never true, ``a OR NULL`` is true
    when ``a`` is. Under NOT (or in any other position) a NULL cannot be decided without evaluating rows:
    that raises rather than answering wrongly."""
    from .lazy_expr import lit
    if _is_null(p):
        return lit(False)
    if isinstance(p, Expr) and p.op in ("and", "or"):
        kids = [_top_truth(a) for a in p.args]
        out = _fold_subquery_value(p.op, kids)
        if out is None:
            out = Expr(p.op, *kids)
        out._alias = p._alias
        return out

    def has_null(e):
        return _is_null(e) or (isinstance(e, Expr) and any(has_null(a) for a in e.args if isinstance(a, Expr)))

    if has_null(p):
        raise ValueError("a scalar subquery over no rows is NULL: not supported under NOT or inside an "
                         "expression that is not a plain comparison")
    return p


def _plan_key(x):
    """Hashable identity of a plan or expression: structure, aliases and literals (arrays by dtype, shape and
    bytes), and the object identity of in-memory tables (``Scan.signature`` has only the column names).
    None for the WHOLE key when any part cannot be keyed, so two plans are never merged on a guess."""
    import dataclasses
    import numpy as np

    def key(x):
        if isinstance(x, Scan):
            return ("Scan", id(x.table))
        if isinstance(x, LogicalPlan):
            if isinstance(x, ParquetScan):
                return x.signature()
            return (type(x).__name__,) + tuple(key(getattr(x, f.name)) for f in dataclasses.fields(x))
        if isinstance(x, Expr):
            return ("e", x.op, tuple(key(a) for a in x.args), x._alias,
                    tuple(sorted((k, key(v)) for k, v in x.kwargs.items())))
        if isinstance(x, (list, tuple)):
            return ("l",) + tuple(key(a) for a in x)
        if isinstance(x, np.ndarray):
            return ("nd", x.dtype.str, x.shape, x.tobytes())
        hash(x)                                   # TypeError: unhashable, the whole key is None
        return (type(x).__name__, x)

    try:
        return key(x)
    except Exception:
        return None


def _ends_in_aggregate(plan) -> bool:
    """True when ``plan``'s output is an aggregate's (one row per group, possibly filtered / projected /
    sorted / limited afterwards): small, and the only place float sums come from."""
    while isinstance(plan, (Filter, Project, Sort, Limit)):
        plan = plan.input
    return isinstance(plan, Aggregate)


def _scalar_inputs(plan):
    """Keys of the plans some scalar subquery of ``plan`` aggregates over, when that same plan also occurs in
    ``plan`` itself outside any scalar (``view.filter(col("t") == view.scalar(col("t").max()))``)."""
    import dataclasses
    scalars, nodes = [], []

    def expr(e):
        if isinstance(e, Expr):
            if e.op == "scalar":
                scalars.append(e.args[0])
            else:
                for a in e.args:
                    expr(a)
        elif isinstance(e, (list, tuple)):
            for a in e:
                expr(a)

    def walk(n):
        if isinstance(n, LogicalPlan):
            nodes.append(n)
            for f in dataclasses.fields(n):
                v = getattr(n, f.name)
                if isinstance(v, LogicalPlan):
                    walk(v)
                else:
                    expr(v)

    walk(plan)
    wanted = {}
    for sc in scalars:
        inp = getattr(sc, "input", None)
        if isinstance(inp, LogicalPlan) and _ends_in_aggregate(inp):       # small output; not a join or a scan
            k = _plan_key(inp)
            if k is not None:
                wanted[k] = None
    return {k for k in wanted if any(_plan_key(n) == k for n in nodes)}


def _resolve_scalars(plan, device: str, strict: bool):
    """``plan`` with every scalar subquery (``LazyFrame.scalar``) in its expressions replaced by the literal it
    computes: each is run first through ``compute`` (so it takes the native path like any plan). The same
    object when the plan has none. A filter whose predicate is constant afterwards (an empty subquery) is
    ``Limit(0)`` or nothing."""
    import dataclasses
    from .lazy_expr import lit

    # A subquery over the same aggregate plan the outer plan also contains (Q15: `view.filter(tot == view.scalar(max))`)
    # shares ONE result: the plan is computed once, the subquery aggregates that table and the outer plan
    # reads it, so the comparison never depends on a float sum coming out twice with the same bits.
    shared = _scalar_inputs(plan)
    mats = {}

    def materialized(inp):
        k = _plan_key(inp)
        if k not in shared:
            return None
        if k not in mats:
            mats[k] = Scan(LazyFrame(inp).compute(device=device, strict=strict))
        return mats[k]

    def expr(e):
        if not isinstance(e, Expr):
            return e
        if e.op == "scalar":
            sub = e.args[0]
            m = materialized(sub.input) if isinstance(sub, Aggregate) else None
            if m is not None:
                sub = dataclasses.replace(sub, input=m)
            out = LazyFrame(sub).compute(device=device, strict=strict)
            new = lit(out.column(0)[0].as_py())          # None: the subquery had no rows (NULL)
            new._alias = e._alias
            return new
        args = tuple(expr(a) if isinstance(a, Expr) else a for a in e.args)
        if all(n is o for n, o in zip(args, e.args)):
            return e
        new = _fold_subquery_value(e.op, args)
        if new is None:
            new = Expr(e.op, *args, **e.kwargs)
        new._alias = e._alias
        return new

    def walk(node):
        if not isinstance(node, LogicalPlan):
            return node
        if shared and not isinstance(node, (Scan, ParquetScan)):
            m = materialized(node)
            if m is not None:
                return m
        changes = {}
        for f in dataclasses.fields(node):
            v = getattr(node, f.name)
            if isinstance(v, LogicalPlan):
                nv = walk(v)
            elif isinstance(v, Expr):
                nv = expr(v)
                if isinstance(node, Filter) and nv is not v:
                    nv = _top_truth(nv)
            elif isinstance(v, list) and any(isinstance(x, Expr) for x in v):
                nv = [expr(x) for x in v]
                if all(n is o for n, o in zip(nv, v)):
                    nv = v
            else:
                continue
            if nv is not v:
                changes[f.name] = nv
        out = dataclasses.replace(node, **changes) if changes else node
        if isinstance(out, Filter) and "predicate" in changes:
            b = _bool_of(out.predicate)
            if b is True:
                return out.input
            if b is False:
                # no row can pass: an empty table of the same columns, so the input (a join of big Parquet files, say)
                # is never run or streamed; Limit(0) where the columns cannot be named without running it
                from .io_parquet import _leaves
                if any(isinstance(l, ParquetScan) for l in _leaves(out.input)):       # (in-memory inputs run as before)
                    names = LazyFrame(out.input).schema
                    if names is not None:
                        return Scan(_empty(names))
                return Limit(out.input, 0)
        return out

    return walk(plan)


def _auto_may_count_codes(plan, prefer, placement) -> bool:
    """auto resolves a COUNT(DISTINCT b) per a with dictionary codes, as device="cpu" does (F-046h, F-058), unless
    the caller steers it to the GPU, which needs the columns decoded."""
    return prefer != "gpu" and "gpu" not in (placement or {}).values() and _has_count_distinct(plan)


def _auto_codes_decision(plan):
    """A CPU decision for a plan whose COUNT(DISTINCT) input kept dictionary codes (the native count reads them; the
    GPU path cannot), else None and the cost model decides. A Parquet source not yet read (explain) counts as coded."""
    from .io_parquet import _is_dict
    from . import auto_mode as _am
    stack, coded = [plan], False
    while stack and not coded:
        p = stack.pop()
        if isinstance(p, ParquetScan):
            coded = True
        elif isinstance(p, Scan):
            coded = any(_is_dict(t) for t in p.table.schema.types)
        stack.extend(x for x in (getattr(p, "input", None), getattr(p, "left", None), getattr(p, "right", None))
                     if x is not None)
    if not coded:
        return None
    d = _am.AutoDecision("cpu", "COUNT(DISTINCT) per key counts dictionary codes on the cpu", None)
    d.cpu_path = "native executor (count distinct on codes)"
    return d


def _has_count_distinct(plan) -> bool:
    """Does the plan hold a COUNT(DISTINCT b) per a (the shape the native count runs on dictionary codes)?"""
    from .io_parquet import count_distinct_shape
    stack = [plan]
    while stack:
        p = stack.pop()
        if count_distinct_shape(p):
            return True
        stack.extend(x for x in (getattr(p, "input", None), getattr(p, "left", None), getattr(p, "right", None))
                     if x is not None)
    return False


def _run_on_device(plan, device: str, *, verbose: bool = False, optimizer_trace=None, strict: bool = False,
                   auto: bool = False):
    """Execute an already optimized plan on one device; returns (result, provenance). A GPU piece that
    left the GPU for memory reasons is listed in the provenance as ``gpu_pieces`` (F-056)."""
    from mxframe import gpu_budget
    from mxframe.custom_ops import CustomOpsCompiler
    compiler = CustomOpsCompiler(device=device)
    with gpu_budget.track(strict=strict, device="auto" if auto else device) as run:
        result = compiler.compile_and_run(plan, verbose=verbose, optimizer_trace=optimizer_trace)
    prov = dict(compiler.last_compile_provenance or {})
    if run.events:
        prov["gpu_pieces"] = "; ".join(run.lines)
        if run.oom_free is not None:
            prov["gpu_pieces_oom"] = run.oom_free      # free GPU bytes when a piece ran out of memory
    return result, prov


def _oom_free(err: BaseException):
    """Free GPU bytes now if `err` is an out-of-memory (the shape is retried once more is free), else None."""
    if not isinstance(err, MemoryError):
        return None
    try:
        from mxframe import gpu_budget
        return gpu_budget.free_bytes()
    except Exception:
        return None
